//! Generates the syntax tree's `SyntaxKind` and typed syntax views from
//! `crates/ferrion_syntax/java.grammar`, and formats them with rustfmt, and the JSON Schema of
//! `ferrion.jsonc` from the config's key tables (`crates/ferrion_config/src/keys.rs`). Run it with
//! `cargo codegen` after changing either; CI checks that the generated files are up to date.

mod ast;
mod grammar;
mod kinds;

use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

const GRAMMAR: &str = "crates/ferrion_syntax/java.grammar";
const KINDS: &str = "crates/ferrion_syntax/src/syntax_kind/generated.rs";
const AST: &str = "crates/ferrion_syntax/src/ast/generated.rs";

/// The first lines of every generated file.
pub const HEADER: &str = "\
// Generated by `cargo codegen` (tools/codegen) from crates/ferrion_syntax/java.grammar. Don't
// edit it by hand: change the grammar and run `cargo codegen`.
";

fn main() -> ExitCode {
    if std::env::args().len() > 1 {
        eprintln!(
            "usage: codegen\n\nRegenerates {KINDS} and {AST} from {GRAMMAR}, and {}.",
            ferrion_config::SCHEMA_PATH
        );
        return ExitCode::FAILURE;
    }
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> Result<(), String> {
    let root = workspace_root();
    let text = std::fs::read_to_string(root.join(GRAMMAR))
        .map_err(|e| format!("can't read {GRAMMAR}: {e}"))?;
    let grammar = grammar::parse(&text).map_err(|e| format!("{GRAMMAR}: {e}"))?;
    grammar
        .check_enums()
        .map_err(|e| format!("{GRAMMAR}: {e}"))?;
    let kinds = kinds::generate(&grammar)?;
    let ast = ast::generate(&grammar).map_err(|e| format!("{GRAMMAR}: {e}"))?;
    for (path, contents) in [(KINDS, kinds), (AST, ast)] {
        let path = root.join(path);
        std::fs::write(&path, contents)
            .map_err(|e| format!("can't write {}: {e}", path.display()))?;
        rustfmt(&path)?;
    }
    let schema = root.join(ferrion_config::SCHEMA_PATH);
    std::fs::create_dir_all(schema.parent().unwrap())
        .map_err(|e| format!("can't create {}: {e}", schema.display()))?;
    std::fs::write(&schema, ferrion_config::json_schema())
        .map_err(|e| format!("can't write {}: {e}", schema.display()))?;
    Ok(())
}

/// The workspace root: two levels above this crate's manifest.
fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .unwrap()
        .to_owned()
}

fn rustfmt(path: &Path) -> Result<(), String> {
    let status = Command::new("rustfmt")
        .args(["--edition", "2024"])
        .arg(path)
        .status()
        .map_err(|e| format!("can't run rustfmt: {e}"))?;
    if status.success() {
        Ok(())
    } else {
        Err(format!("rustfmt failed on {}", path.display()))
    }
}

/// `IfStmt` to `if_stmt`.
pub fn snake_case(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}
